package app.kivo.store;
import android.app.*;import android.widget.EditText;import org.json.*;import java.util.*;import java.io.*;import java.util.concurrent.*;
/** Public reviews live only in an explicitly configured Kivo repository, never upstream app repos. */
final class Community {
 final MainActivity host;final ExecutorService jobs=Executors.newSingleThreadExecutor();volatile String repository="";volatile boolean posting;volatile long freshUntil;final Map<String,Long> threads=new ConcurrentHashMap<>();final Map<String,Long> threadTimes=new ConcurrentHashMap<>();final Map<String,List<Long>> threadGroups=new ConcurrentHashMap<>();
 Community(MainActivity h){host=h;try(InputStream in=h.getAssets().open("community.json")){repository=new JSONObject(MainActivity.read(in,2000)).optString("repository");}catch(Exception ignored){}if(repository.isEmpty())repository=h.prefs.getString("communityRepo","");}
 void state(){try{host.send("communityState",new JSONObject().put("configured",!repository.isEmpty()).put("repository",repository));}catch(Exception ignored){}}
 JSONObject app(String raw){try{String repo=MainActivity.repo(raw);JSONObject a=host.catalog.get(repo);if(a==null)a=host.sourceEntry(repo);if(a!=null&&a.optString("package").isEmpty()){String pkg=host.prefs.getString("pkg:"+repo,"");if(InstalledApps.validPackage(pkg))a=new JSONObject(a.toString()).put("package",pkg);}return a;}catch(Exception e){return null;}}
 boolean canReview(String repo,JSONObject a){if(a==null)return false;String pkg=a.optString("package");if(!host.installedApps.installed(pkg))return false;try{int flags=android.os.Build.VERSION.SDK_INT>=28?android.content.pm.PackageManager.GET_SIGNING_CERTIFICATES:android.content.pm.PackageManager.GET_SIGNATURES;String signer=host.signers(host.getPackageManager().getPackageInfo(pkg,flags));JSONArray verified=new JSONArray();for(Map.Entry<String,?> entry:host.prefs.getAll().entrySet())if(entry.getKey().startsWith("verified:"))try{JSONObject record=new JSONObject(String.valueOf(entry.getValue()));record.put("signer",host.prefs.getString("sign:"+entry.getKey().substring(9),""));verified.put(record);}catch(Exception ignored){}return ReviewEligibility.allows(pkg,signer,verified);}catch(Exception e){return false;}}
 JSONObject eligibilityResult(String repo,JSONObject a)throws Exception{String pkg=a==null?"":a.optString("package");boolean eligible=canReview(repo,a);return new JSONObject().put("repo",repo).put("configured",!repository.isEmpty()).put("eligible",eligible).put("eligibilityKnown",true).put("reason",eligible?"":!InstalledApps.validPackage(pkg)?"Falta identificar el paquete Android. Instala la app desde Kivo y vuelve a abrir la ficha.":!host.installedApps.installed(pkg)?"Primero instala la app. Descargar el APK todavía no cuenta como instalación.":"La instalación está presente, pero falta comprobar que proviene de una descarga verificada de Kivo.");}
 void eligibility(String raw){JSONObject a=app(raw);if(a==null)return;try{host.send("communityEligibility",eligibilityResult(a.optString("repo"),a));}catch(Exception ignored){}}
 void setup(){EditText input=new EditText(host);input.setSingleLine(true);input.setHint("propietario/kivo-comunidad");input.setText(repository);new AlertDialog.Builder(host).setTitle("Repositorio de la comunidad Kivo").setMessage("Configuración del propietario. Debe ser un repositorio público dedicado, con Issues y el archivo .kivo-community.json. Todos los usuarios necesitan la misma configuración.").setView(input).setPositiveButton("Validar",(d,w)->jobs.execute(()->{try{String repo=MainActivity.repo(input.getText().toString());validateRepository(repo);repository=repo;threads.clear();threadTimes.clear();threadGroups.clear();host.prefs.edit().putString("communityRepo",repo).apply();state();host.status("Repositorio de comunidad validado.");}catch(Exception e){host.status("No se configuró la comunidad: "+e.getMessage());}})).setNegativeButton("Cancelar",null).show();}
 void validateRepository(String repo)throws Exception{JSONObject meta=host.get("repos/"+repo);if(meta.optBoolean("private",true)||!meta.optBoolean("has_issues")||meta.optBoolean("archived")||meta.optBoolean("disabled"))throw new IOException("Necesita ser público, activo y tener Issues.");JSONObject marker=host.get("repos/"+repo+"/contents/.kivo-community.json");String text=new String(android.util.Base64.decode(marker.getString("content"),android.util.Base64.DEFAULT),"UTF-8");if(!new JSONObject(text).optString("kind").equals("kivo-community-v1"))throw new IOException("Falta el identificador de comunidad Kivo.");}
 long thread(String pkg)throws Exception{Long cached=threads.get(pkg);if(cached!=null&&System.currentTimeMillis()-threadTimes.getOrDefault(pkg,0L)<300000)return cached;long selected=0;List<Long> found=new ArrayList<>();for(int page=1;page<=10;page++){JSONArray rows=host.github.get("repos/"+repository+"/issues?state=all&per_page=100&page="+page,host.sessionToken,System.currentTimeMillis()<freshUntil?0:60000).getJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject issue=rows.optJSONObject(i);if(issue==null||issue.has("pull_request"))continue;try{JSONObject body=new JSONObject(issue.optString("body"));if(body.optString("kind").equals("kivo-app-v1")&&pkg.equals(body.optString("package"))){long number=issue.getLong("number");if(selected==0||number<selected)selected=number;found.add(number);}}catch(Exception ignored){}}if(rows.length()<100)break;if(page==10)throw new IOException("No se pudo revisar el índice completo de opiniones. Inténtalo más tarde.");}threads.put(pkg,selected);threadTimes.put(pkg,System.currentTimeMillis());threadGroups.put(pkg,found);return selected;}
 void read(String raw){final JSONObject a=app(raw);if(a==null)return;final String repo=a.optString("repo"),pkg=a.optString("package");eligibility(raw);jobs.execute(()->{try{state();if(repository.isEmpty()){host.send("community",new JSONObject().put("repo",repo).put("configured",false));return;}if(!InstalledApps.validPackage(pkg))throw new IOException("La fuente todavía no declara el identificador Android de esta app.");long issue=thread(pkg);JSONArray all=new JSONArray();boolean complete=true;if(issue>0){List<Long> groups=threadGroups.getOrDefault(pkg,Collections.singletonList(issue));if(groups.size()>5)complete=false;for(long group:groups.subList(0,Math.min(5,groups.size()))){for(int page=1;page<=10;page++){JSONArray rows=host.github.get("repos/"+repository+"/issues/"+group+"/comments?per_page=100&page="+page,host.sessionToken,System.currentTimeMillis()<freshUntil?0:60000).getJSONArray("items");for(int i=0;i<rows.length();i++)all.put(rows.get(i));if(rows.length()<100)break;if(page==10)complete=false;}}}JSONObject result=ReviewPolicy.aggregate(all,pkg);JSONObject local=eligibilityResult(repo,a);for(String key:new String[]{"repo","configured","eligible","eligibilityKnown","reason"})result.put(key,local.get(key));result.put("complete",complete);host.send("community",result);}catch(Exception e){try{host.send("community",eligibilityResult(repo,a).put("error",e.getMessage()==null?"No se pudieron leer las reseñas.":e.getMessage()));}catch(Exception ignored){}}});}
 void confirm(String raw,int rating,String text){JSONObject a=app(raw);if(a==null)return;String repo=a.optString("repo");try{ReviewPolicy.body(a.optString("package"),rating,text);if(repository.isEmpty())throw new IOException("El propietario todavía debe configurar la comunidad Kivo.");if(host.sessionToken.isEmpty()){host.loginDialog();return;}if(!canReview(repo,a))throw new IOException("Primero instala esta app desde Kivo. La instalación debe estar presente en este celular.");if(posting)throw new IOException("Espera a que termine la publicación actual.");new AlertDialog.Builder(host).setTitle("Publicar reseña de "+a.optString("name")).setMessage("Tu nombre de GitHub, calificación "+rating+"/5 y comentario serán públicos en "+repository+". Una calificación por cuenta; puedes actualizarla. El comentario no se enviará al repositorio del desarrollador.\n\n"+text).setPositiveButton("Publicar",(d,w)->write(repo,a,rating,text)).setNegativeButton("Cancelar",null).show();}catch(Exception e){host.status(e.getMessage());}}
 void write(String repo,JSONObject a,int rating,String text){if(posting)return;posting=true;final String target=repository,token=host.sessionToken;jobs.execute(()->{try{validateRepository(target);if(!target.equals(repository)||!canReview(repo,a)||!token.equals(host.sessionToken))throw new IOException("La configuración o sesión cambió; vuelve a abrir la reseña.");String pkg=a.getString("package"),login=host.github.get("user",token,0).getString("login");if(threads.getOrDefault(pkg,-1L)==0){threads.remove(pkg);threadTimes.remove(pkg);freshUntil=System.currentTimeMillis()+10000;}long issue=thread(pkg);if(issue==0){JSONObject created=host.github.mutate("repos/"+target+"/issues",token,"POST",new JSONObject().put("title","[Kivo] "+pkg).put("body",new JSONObject().put("kind","kivo-app-v1").put("package",pkg).toString()));issue=created.getLong("number");threads.put(pkg,issue);threadTimes.put(pkg,System.currentTimeMillis());threadGroups.put(pkg,Collections.singletonList(issue));}
  long own=0;for(int page=1;page<=10;page++){JSONArray rows=host.github.get("repos/"+target+"/issues/"+issue+"/comments?per_page=100&page="+page,token,0).getJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject c=rows.getJSONObject(i);if(login.equalsIgnoreCase(c.getJSONObject("user").optString("login")))try{JSONObject b=new JSONObject(c.optString("body"));if(b.optString("kind").equals("kivo-review-v1")&&pkg.equals(b.optString("package")))own=c.getLong("id");}catch(Exception ignored){}}if(rows.length()<100)break;if(page==10)throw new IOException("El hilo necesita moderación antes de publicar más reseñas desde esta versión.");}
  String path=own>0?"repos/"+target+"/issues/comments/"+own:"repos/"+target+"/issues/"+issue+"/comments";host.github.mutate(path,token,own>0?"PATCH":"POST",new JSONObject().put("body",ReviewPolicy.body(pkg,rating,text)));freshUntil=System.currentTimeMillis()+10000;host.status("Reseña publicada en GitHub.");read(repo);
 }catch(Exception e){host.status("No se confirmó la reseña: "+e.getMessage());}finally{posting=false;}});}
 void close(){jobs.shutdownNow();}
}
